// Extract url_citation annotations from the search-enabled response.
// Citations arrive as structured data; no LLM judge needed here.
const meta = $('Batch Process Samples').item.json;
const msg = $json.choices?.[0]?.message || {};
const annotations = msg.annotations || [];
const out = [];
for (const a of annotations) {
  if (a.type === 'url_citation' && a.url_citation?.url) {
    let domain = '';
    try { domain = new URL(a.url_citation.url).hostname.replace(/^www\./, ''); } catch (e) { continue; }
    out.push({ json: {
      query_id: meta.query_id,
      query: meta.query,
      brand: meta.brand,
      competitors: meta.competitors,
      sample: meta.sample,
      total_samples: meta.total_samples,
      domain,
      url: a.url_citation.url,
      title: a.url_citation.title || ''
    } });
  }
}
// Emit a marker item even when a sample has no citations,
// so hit-rate math stays honest.
if (out.length === 0) {
  out.push({ json: { ...meta, domain: null, url: null, title: null } });
}
return out;

// Aggregate: per query + domain, count citations and sample hit rate.
// Output is ONE item carrying rows + the unique domain list, so the
// classification step runs as a single API call.
const byKey = {};
const samplesPerQuery = {};
const brands = {};
for (const item of $input.all()) {
  const j = item.json;
  samplesPerQuery[j.query_id] = j.total_samples;
  brands[j.query_id] = { brand: j.brand, competitors: j.competitors, query: j.query };
  if (!j.domain) continue;
  const key = j.query_id + '||' + j.domain;
  if (!byKey[key]) byKey[key] = { query_id: j.query_id, domain: j.domain, citations: 0, samples_hit: new Set(), example_url: j.url };
  byKey[key].citations += 1;
  byKey[key].samples_hit.add(j.sample);
}
const today = new Date().toISOString().slice(0, 10);
const rows = Object.values(byKey).map(r => ({
  run_date: today,
  query_id: r.query_id,
  query: brands[r.query_id].query,
  domain: r.domain,
  citations: r.citations,
  sample_hit_rate: Math.round((r.samples_hit.size / (samplesPerQuery[r.query_id] || 1)) * 100) + '%',
  example_url: r.example_url
}));
rows.sort((a, b) => a.query_id.localeCompare(b.query_id) || b.citations - a.citations);
const uniqueDomains = [...new Set(rows.map(r => r.domain))];
const anyQ = Object.keys(brands)[0];
return [{ json: {
  rows,
  unique_domains: uniqueDomains,
  brand: anyQ ? brands[anyQ].brand : '',
  competitors: anyQ ? brands[anyQ].competitors : ''
} }];

