// Join source_type classifications back onto the aggregated rows.
const agg = $('Aggregate Citation Data').item.json;
let mapping = {};
try {
  mapping = JSON.parse($json.choices[0].message.content);
} catch (e) {
  mapping = {};
}
return agg.rows.map(r => ({ json: { ...r, source_type: mapping[r.domain] || 'unclassified' } }));
